<?php
 namespace Pterodactyl\Notifications; use Illuminate\Bus\Queueable; use Pterodactyl\Services\Dezerx\Emails; use Illuminate\Notifications\Notification; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; class SendPasswordReset extends Notification implements ShouldQueue { use Queueable; public function __construct(public string $token) { } public function via(): array { return ['mail']; } public function toMail(mixed $notifiable): MailMessage { return Emails::apply(new MailMessage(), 'password-reset', [ 'name' => (string) ($notifiable->name ?? $notifiable->username ?? ''), 'email' => (string) $notifiable->email, ], url('/auth/password/reset/' . $this->token . '?email=' . urlencode($notifiable->email))); } } 